// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Every non-generic viz id must appear here, and the `Record<Exclude<AppCardVizId,
 * 'generic'>, true>` type means TypeScript fails the build if a new union member
 * is added without a template flag (or vice versa). Adding a new viz = extend
 * `AppCardVizId`, flip it `true` here, and add the switch case in `renderVizInner`.
 *
 * NB: this map is NOT derived from `apps.config.yml`. The config lists which apps
 * exist; this lists which apps have a hand-authored visual template. Unknown ids
 * fall through to the generic monogram, so new apps can ship without art.
 */
const VIZ_TEMPLATES: Record<Exclude<AppCardVizId, 'generic'>, true> = {
  markdown: true, school: true, earth: true, cosmos: true,
  techscope: true, citypulse: true, stockpulse: true, weather: true, daily: true,
  csvexplorer: true, chartbuilder: true, pad: true, regexlab: true,
  jsonexplorer: true, codediff: true, playground: true, jwtinspector: true,
  colorlab: true, cronbuilder: true, apiexplorer: true, movies: true,
  promptlab: true, imagegen: true, games: true,
};

function resolveVizId(id: string): AppCardVizId {
  return Object.prototype.hasOwnProperty.call(VIZ_TEMPLATES, id)
    ? (id as AppCardVizId)
    : 'generic';
}

function monogram(label: string): string {
  const parts = label.trim().split(/\s+/).filter(Boolean);
  if (parts.length === 0) return '··';
  if (parts.length === 1) {
    const word = parts[0];
    return (word[0] + (word[1] ?? '·')).toUpperCase().slice(0, 2);
  }
  return (parts[0][0] + parts[1][0]).toUpperCase();
}

