const COLORLAB_SWATCHES = ['#f78166', '#d29922', '#3fb950', '#58a6ff', '#a371f7'];

const TECHSCOPE_BARS = [40, 65, 52, 78, 30, 88, 45, 70, 58, 82, 35, 62, 72, 48, 90, 55];

function renderVizInner(vizId: AppCardVizId, label: string, accentColor: string): ReactNode {
  switch (vizId) {
    case 'markdown':
      return (
        <>
          <span className="h" />
          <span className="l1" />
          <span className="l2" />
          <span className="l3" />
          <span className="l4" />
        </>
      );
    case 'school':
      return (
        <>
          <span className="lb">School</span>
          <div className="col" />
          <div className="col" />
          <div className="col" />
          <div className="col" />
        </>
      );
    case 'earth':
      return <div className="g" />;
    case 'cosmos':
      return null;
    case 'techscope':
      return (
        <>
          {TECHSCOPE_BARS.map((h, i) => (
            <span key={i} style={{ height: `${h}%` }} />
          ))}
        </>
      );
    case 'citypulse':
      return null;
    case 'stockpulse':
      return (
        <>
          {[0, 1, 0, 0, 1, 0, 0, 0, 1, 0, 0, 0].map((red, i) => (
            <div key={i} className={red ? 'c r' : 'c'} />
          ))}
        </>
      );
    case 'csvexplorer':
      return (
        <>
          <span className="h">id</span>
          <span className="h">name</span>
          <span className="h">qty</span>
          <span className="h">px</span>
          <span>01</span>
          <span>alfa</span>
          <span>12</span>
          <span>1.2</span>
          <span>02</span>
          <span>beta</span>
          <span>8</span>
          <span>0.9</span>
        </>
      );
    case 'chartbuilder':
      return null;
    case 'pad':
      return (
        <>
          <span className="t" />
          <span className="a" />
          <span className="b" />
          <span className="c" />
          <span className="d" />
        </>
      );
    case 'regexlab':
      return (
        <>
          <span className="slash">/</span>
          <span>(</span>
          <span className="hl">[a-z]+</span>
          <span>)</span>
          <span className="slash">/g</span>
        </>
      );
    case 'jsonexplorer':
      return (
        <>
          <span className="b">{'{'}</span>
          <br />
          &nbsp;&nbsp;<span className="k">"user"</span>: <span className="v">"dev"</span>,
          <br />
          &nbsp;&nbsp;<span className="k">"apps"</span>: <span className="b">[</span>
          <br />
          &nbsp;&nbsp;&nbsp;&nbsp;<span className="v">"markdown"</span>,
          <br />
          &nbsp;&nbsp;&nbsp;&nbsp;<span className="v">"school"</span>
          <br />
          &nbsp;&nbsp;<span className="b">]</span>
          <br />
          <span className="b">{'}'}</span>
        </>
      );
    case 'codediff':
      return (
        <>
          <div className="col">
            <span className="a" />
            <span className="n" style={{ width: '70%' }} />
            <span className="a" />
            <span className="n" style={{ width: '55%' }} />
            <span className="n" />
            <span className="n" style={{ width: '80%' }} />
          </div>
          <div className="col">
            <span className="g" />
            <span className="n" style={{ width: '70%' }} />
            <span className="g" />
            <span className="g" />
            <span className="n" style={{ width: '55%' }} />
            <span className="n" style={{ width: '80%' }} />
          </div>
        </>
      );
    case 'playground':
      return (
        <>
          <div className="tube" />
          <div className="tube" style={{ height: 45 }} />
          <div className="tube" style={{ height: 50 }} />
        </>
      );
    case 'jwtinspector':
      return (
        <>
          <span className="h">header</span>
          <span className="sep">·</span>
          <span className="p">payload</span>
          <span className="sep">·</span>
          <span className="s">sig</span>
        </>
      );
    case 'colorlab':
      return (
        <>
          {COLORLAB_SWATCHES.map((c) => (
            <span key={c} style={{ background: c }} />
          ))}
        </>
      );
    case 'cronbuilder':
      return (
        <>
          <div className="row" data-l="m">
            <span /><span className="on" /><span /><span /><span className="on" /><span /><span /><span className="on" /><span /><span /><span className="on" /><span />
          </div>
          <div className="row" data-l="h">
            <span className="on" /><span /><span /><span /><span className="on" /><span /><span /><span /><span className="on" /><span /><span /><span />
          </div>
          <div className="row" data-l="d">
            <span /><span /><span className="on" /><span /><span /><span /><span className="on" /><span /><span /><span /><span className="on" /><span />
          </div>
        </>
      );
    case 'weather':
      return (
        <>
          <div className="sun" />
          <div className="temp">15<small>°</small></div>
        </>
      );
    case 'apiexplorer':
      return (
        <>
          <div><span className="get">GET</span> <span className="url">/api/v1/users/me</span></div>
          <div><span className="status">200 OK</span> · 42 ms</div>
          <div className="echo">{'→ { id: 1, role: "dev" }'}</div>
        </>
      );
    case 'movies':
      return (
        <>
          {POSTER_GRADIENTS.map((g, i) => (
            <span key={i} style={{ background: g }} />
          ))}
        </>
      );
    case 'promptlab':
      return (
        <>
          <div className="bubble">Write a haiku about the fog at 6am.</div>
          <div className="bubble r">Low mist. Bridge lamps hum. The ferry horn splits the grey…</div>
        </>
      );
    case 'imagegen':
      return <div className="frame" />;
    case 'daily':
      return (
        <>
          <div className="ring r1" />
          <div className="ring r2" />
          <div className="ring r3" />
          <div className="dot" />
        </>
      );
    case 'games':
      return (
        <>
          {GAME_TILES.map((t, i) => (
            <span key={i} style={{ background: t.bg, color: t.fg ?? theme.colors.mainText }}>{t.glyph}</span>
          ))}
        </>
      );
    case 'generic':
    default:
      return <span className="viz-mono" style={{ color: accentColor }}>{monogram(label)}</span>;
  }
}

// ─── Component ────────────────────────────────────────────────────────────────

export function AppCard({
  vizId,
  label,
  description,
  hash,
  category,
  accentColor,
  needsAuth,
  pinned,
  index = 0,
  onClick,
  onTogglePin,
  reorderControls,
}: AppCardProps) {
  const resolved = resolveVizId(vizId);

  const handlePinClick = (e: MouseEvent<HTMLButtonElement>) => {
    e.stopPropagation();
    onTogglePin?.();
  };

  return (
    <Root
      type="button"
      accentColor={accentColor}
      pinned={pinned}
      index={index}
      onClick={onClick}
    >
      {reorderControls && (
        <ReorderSlot className="pin-controls">{reorderControls}</ReorderSlot>
      )}
      {onTogglePin && (
        <PinBtnRoot
          className="pin-btn"
          type="button"
          pinned={!!pinned}
          aria-label={pinned ? 'Unpin' : 'Pin to top'}
          onClick={handlePinClick}
        >
          <Pin size={14} fill={pinned ? 'currentColor' : 'none'} />
        </PinBtnRoot>
      )}
      <Viz className={`viz viz--${resolved}`} accentColor={accentColor}>
        {renderVizInner(resolved, label, accentColor)}
      </Viz>
      <MetaRow accentColor={accentColor}>
        <span className="dot" />
        <span className="cat">{category}</span>
        {needsAuth && <span className="lock">◉ AUTH</span>}
      </MetaRow>
      <Body>
        <Title>
          {label}
          <span className="hash">{hash}</span>
        </Title>
        <Desc>{description}</Desc>
      </Body>
    </Root>
  );
}
