import React, { useEffect, useRef, useState } from 'react';
import styled from '@emotion/styled';
import { theme } from '@atlantis/shared';

const Wrapper = styled.div`
  position: relative;
  display: inline-flex;
`;

const Menu = styled.div<{ align: 'left' | 'right' }>`
  position: absolute;
  top: calc(100% + 6px);
  ${({ align }) => (align === 'right' ? 'right: 0;' : 'left: 0;')}
  min-width: 180px;
  padding: 4px;
  display: flex;
  flex-direction: column;
  background: ${theme.colors.sidebarBg};
  border: 1px solid ${theme.colors.sidebarBorder};
  border-radius: ${theme.borderRadius.md};
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.5);
  z-index: 2000;
  overflow: hidden;
`;

export interface DropdownProps {
  /** The trigger — typically a `<Button>`. Receives `onClick` + `aria-expanded`. */
  trigger: React.ReactElement;
  /** Menu content — typically a list of `<DropdownItem>` */
  children: React.ReactNode;
  /** Menu alignment relative to the trigger (default: right) */
  align?: 'left' | 'right';
  /** Controlled open state (optional). If omitted, uses internal state. */
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
}

export function Dropdown({
  trigger,
  children,
  align = 'right',
  open: controlledOpen,
  onOpenChange,
}: DropdownProps) {
  const [internalOpen, setInternalOpen] = useState(false);
  const open = controlledOpen ?? internalOpen;
  const setOpen = (v: boolean) => {
    if (onOpenChange) onOpenChange(v);
    if (controlledOpen === undefined) setInternalOpen(v);
  };

  const wrapRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!open) return;
    const onDown = (e: MouseEvent) => {
      if (wrapRef.current && !wrapRef.current.contains(e.target as Node)) {
        setOpen(false);
      }
    };
    document.addEventListener('mousedown', onDown);
    return () => document.removeEventListener('mousedown', onDown);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open]);

  const triggerWithHandlers = React.cloneElement(trigger, {
    onClick: (e: React.MouseEvent) => {
      trigger.props.onClick?.(e);
      setOpen(!open);
    },
    'aria-expanded': open,
    'aria-haspopup': 'menu',
  });

  return (
    <Wrapper ref={wrapRef}>
      {triggerWithHandlers}
      {open && <Menu align={align} role="menu">{children}</Menu>}
    </Wrapper>
  );
}

export const DropdownItem = styled.button`
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 12px;
  background: none;
  border: none;
  border-radius: ${theme.borderRadius.sm};
  color: ${theme.colors.mainText};
  font-size: ${theme.typography.fontSizeSm};
  font-family: ${theme.typography.fontFamily};
  cursor: pointer;
  text-align: left;
  transition: background 0.12s, color 0.12s;
  white-space: nowrap;

  &:hover {
    background: ${theme.colors.sidebarHover};
    color: ${theme.colors.accent};
  }
  &:focus-visible {
    outline: 2px solid ${theme.colors.accent};
    outline-offset: -2px;
  }
`;

export const DropdownDivider = styled.div`
  height: 1px;
  margin: 4px 0;
  background: ${theme.colors.sidebarBorder};
`;

export const DropdownLabel = styled.div`
  padding: 8px 12px 4px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: ${theme.colors.sidebarTextMuted};
  font-family: ${theme.typography.fontFamily};
`;
