const PIN_PREFIX = 'pin:';

function isPinEntry(w: WidgetInstance): boolean {
  return w.widgetId.startsWith(PIN_PREFIX);
}

function pinAppId(w: WidgetInstance): string {
  return w.widgetId.slice(PIN_PREFIX.length);
}

