import { useEffect, useState } from 'react';

export type NavParamValue = string | number | undefined;
export type NavParams = Record<string, NavParamValue>;

/**
 * Navigate to an app, optionally passing params as a query string appended to the hash.
 * Example: navigateTo('earth', { placeId: 'lisbon' }) → '#/earth?placeId=lisbon'
 * Empty or undefined values are skipped.
 */
export function navigateTo(appId: string, params?: NavParams): void {
  const qs = params
    ? Object.entries(params)
        .filter(([, v]) => v !== undefined && v !== '')
        .map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(String(v))}`)
        .join('&')
    : '';
  window.location.hash = qs ? `#/${appId}?${qs}` : `#/${appId}`;
}

/** Parse the current window hash's query string into a flat record. */
export function getNavParams(): Record<string, string> {
  const hash = typeof window !== 'undefined' ? window.location.hash : '';
  const qIdx = hash.indexOf('?');
  if (qIdx === -1) return {};
  const result: Record<string, string> = {};
  for (const pair of hash.slice(qIdx + 1).split('&')) {
    if (!pair) continue;
    const eqIdx = pair.indexOf('=');
    if (eqIdx === -1) {
      result[decodeURIComponent(pair)] = '';
    } else {
      result[decodeURIComponent(pair.slice(0, eqIdx))] = decodeURIComponent(pair.slice(eqIdx + 1));
    }
  }
  return result;
}

/** React hook — reactive to hashchange events. Use in any app to read deep-link params. */
export function useNavParams(): Record<string, string> {
  const [params, setParams] = useState<Record<string, string>>(getNavParams);
  useEffect(() => {
    const onHashChange = () => setParams(getNavParams());
    window.addEventListener('hashchange', onHashChange);
    return () => window.removeEventListener('hashchange', onHashChange);
  }, []);
  return params;
}
