/**
 * Central configuration for all apps.
 *
 * Source of truth: `apps.config.yml`. Edit that file to add/remove apps or
 * change their properties. Set `enabled: false` to hide an app.
 *
 * Every user-visible string goes through `@atlantis/i18n` — `labelKey` and
 * `descriptionKey` are translation keys, not display text. Add the actual
 * copy to `translations.ts` under `apps.<id>.label` / `apps.<id>.description`.
 */
import appsData from './apps.config.yml';
import type { Interest } from '@atlantis/shared';

export interface AppConfig {
  id: string;
  port: number;
  /** Translation key (e.g. 'apps.games.label'). Resolve with `t(config.labelKey)`. */
  labelKey: string;
  /** Translation key (e.g. 'apps.games.description'). Resolve with `t(config.descriptionKey)`. */
  descriptionKey: string;
  /** Primary hash route, e.g. '#/games'. */
  hash: string;
  /** Extra hash prefixes that route to this app (e.g. 'lebem' → games). Primary hash is NOT duplicated here. */
  hashAliases?: string[];
  icon: string;
  color: string;
  enabled: boolean;
  category: string;
  needsAuth: boolean;
  suite?: string;
  homeHidden?: boolean;
  /** If set, the app is hidden when `hasInterests(profile)` is true and
   *  `profile.interests` doesn't include this tag. Apps without `interest`
   *  (tools, utilities) are always shown regardless of selected interests.
   *
   *  Note: `profile.ageMode` is NOT used to hide apps — apps that need to
   *  respect age mode must adjust their own content internally. */
  interest?: Interest;
}

// yaml-loader emits `unknown`; we assert through `AppConfig[]`. Shape is
// validated at review time, and `normalize()` in profile.ts would reject
// bad `interest` values at runtime.
const APPS: AppConfig[] = appsData as AppConfig[];

export default APPS;
