import { useEffect, useState, useMemo } from 'react';
import styled from '@emotion/styled';
import { keyframes } from '@emotion/react';
import { theme } from '@atlantis/shared';
import type { AppDefinition } from '@atlantis/shared';
import type { Locale, TFunction } from '@atlantis/i18n';
import APP_CONFIG from './apps.config';
import { cachedFetch } from './widgets/cachedFetch';

const WEATHER_URL =
  'https://api.open-meteo.com/v1/forecast?latitude=38.7223&longitude=-9.1393' +
  '&current=temperature_2m,apparent_temperature,relative_humidity_2m,weather_code,wind_speed_10m,is_day' +
  '&daily=temperature_2m_max,temperature_2m_min,sunrise,sunset,uv_index_max' +
  '&timezone=Europe%2FLisbon&forecast_days=1';

interface WeatherSnap {
  current: { temperature_2m: number; weather_code: number; is_day: number };
}

const WMO_DAY: Record<number, string> = {
  0: '☀️', 1: '🌤️', 2: '⛅', 3: '☁️', 45: '🌫️', 48: '🌫️',
  51: '🌦️', 53: '🌦️', 55: '🌧️', 61: '🌧️', 63: '🌧️', 65: '🌧️',
  71: '🌨️', 73: '🌨️', 75: '🌨️', 80: '🌦️', 81: '🌧️', 82: '🌧️',
  95: '⛈️', 96: '⛈️', 99: '⛈️',
};
const WMO_NIGHT: Record<number, string> = { 0: '🌙', 1: '🌙', 2: '☁️', 3: '☁️' };

interface RetreatViewProps {
  locale: Locale;
  greeting: string;
  userName?: string;
  pinnedApps: AppDefinition[];
  onSelect: (app: AppDefinition) => void;
  t: TFunction;
}

const APP_ICON = Object.fromEntries(APP_CONFIG.map((a) => [a.id, a.icon]));

function pad(n: number): string { return n < 10 ? `0${n}` : String(n); }

function formatDateKicker(d: Date, locale: Locale): string {
  const weekday = d.toLocaleDateString(locale === 'pt' ? 'pt-PT' : 'en-GB', { weekday: 'long' });
  const day = d.getDate();
  const month = d.toLocaleDateString(locale === 'pt' ? 'pt-PT' : 'en-GB', { month: 'long' });
  return `${weekday} · ${day} ${month}`.toUpperCase();
}

export function RetreatView({ locale, greeting, userName, pinnedApps, onSelect, t }: RetreatViewProps) {
  const [now, setNow] = useState<Date>(() => new Date());
  const [weather, setWeather] = useState<WeatherSnap | null>(null);

  useEffect(() => {
    const id = setInterval(() => setNow(new Date()), 30_000);
    return () => clearInterval(id);
  }, []);

  useEffect(() => {
    let cancelled = false;
    (async () => {
      const data = await cachedFetch<WeatherSnap>(WEATHER_URL, 'weather-lisbon-v3');
      if (!cancelled && data) setWeather(data);
    })();
    return () => { cancelled = true; };
  }, []);

  const time = `${pad(now.getHours())} : ${pad(now.getMinutes())}`;
  const kicker = useMemo(() => formatDateKicker(now, locale), [now, locale]);
  const visibleDots = pinnedApps.slice(0, 5);

  const weatherIcon = weather
    ? (weather.current.is_day
        ? WMO_DAY[weather.current.weather_code]
        : WMO_NIGHT[weather.current.weather_code] ?? WMO_DAY[weather.current.weather_code]) ?? '·'
    : null;

  return (
    <Stage>
      {weather && (
        <Ambient>
          <span className="ico">{weatherIcon}</span>
          <span className="temp">{Math.round(weather.current.temperature_2m)}°</span>
          <span className="lbl">{t('retreat.weather.city')}</span>
        </Ambient>
      )}
      <Inner>
        <Kicker>{kicker}</Kicker>
        <Greeting>
          {greeting}
          {userName ? (<>, <span className="name">{userName.split(' ')[0]}</span></>) : null}
          .
        </Greeting>
        <TimeRow>{time}</TimeRow>
        <Prompt aria-hidden>
          <span className="caret">⌘K</span>
          <span className="txt">{t('retreat.prompt')}</span>
        </Prompt>

        {visibleDots.length > 0 && (
          <DotRow>
            {visibleDots.map((app, i) => (
              <Dot
                key={app.id}
                onClick={() => onSelect(app)}
                title={`${i + 1} · ${app.label}`}
                aria-label={app.label}
              >
                <span className="ico">{APP_ICON[app.id] ?? '·'}</span>
                <span className="n">{i + 1}</span>
              </Dot>
            ))}
          </DotRow>
        )}
      </Inner>
    </Stage>
  );
}

