import React, {
  useState, useEffect, useRef, useCallback, useMemo,
} from 'react';
import ReactDOM from 'react-dom';
import styled from '@emotion/styled';
import { keyframes } from '@emotion/react';
import { theme } from '@atlantis/shared';
import { createT } from '@atlantis/i18n';
import type { Locale } from '@atlantis/i18n';
import { Search, X, ArrowRight, Clock } from 'lucide-react';
import SHELL_KEYS from './translations';

// ── Types ─────────────────────────────────────────────────────────────────────

export interface AppEntry {
  id: string;
  label: string;
  hash: string;
  icon: string;
  description: string;
  color: string;
  category: string;
}

interface Props {
  apps: AppEntry[];
  recentIds: string[];
  locale: Locale;
  onNavigate: (hash: string) => void;
  onClose: () => void;
}

type ListItem =
  | { kind: 'header'; label: string }
  | { kind: 'app'; app: AppEntry; isRecent: boolean };

