// ── Component ─────────────────────────────────────────────────────────────────

export function CommandPalette({ apps, recentIds, locale, onNavigate, onClose }: Props) {
  const t = useMemo(() => createT(locale, SHELL_KEYS), [locale]);
  const [query, setQuery] = useState('');
  const [selectedIndex, setSelectedIndex] = useState(0);
  const inputRef = useRef<HTMLInputElement>(null);
  const listRef  = useRef<HTMLDivElement>(null);

  useEffect(() => { inputRef.current?.focus(); }, []);

  const listItems = useMemo<ListItem[]>(() => {
    const q = query.trim().toLowerCase();

    if (q) {
      const matches = apps.filter((a) =>
        a.label.toLowerCase().includes(q) ||
        a.description.toLowerCase().includes(q) ||
        a.category.toLowerCase().includes(q) ||
        a.id.toLowerCase().includes(q),
      );
      return matches.map((app) => ({ kind: 'app', app, isRecent: false }));
    }

    const recentApps = recentIds
      .map((id) => apps.find((a) => a.id === id))
      .filter((a): a is AppEntry => !!a);

    const recentSet = new Set(recentIds);
    const otherApps = apps.filter((a) => !recentSet.has(a.id));

    const items: ListItem[] = [];

    if (recentApps.length > 0) {
      items.push({ kind: 'header', label: t('palette.recent') });
      recentApps.forEach((app) => items.push({ kind: 'app', app, isRecent: true }));
    }

    if (otherApps.length > 0) {
      items.push({ kind: 'header', label: t('palette.allApps') });
      otherApps.forEach((app) => items.push({ kind: 'app', app, isRecent: false }));
    }

    return items;
  }, [query, apps, recentIds, t]);

  const selectableItems = useMemo(
    () => listItems.filter((i): i is Extract<ListItem, { kind: 'app' }> => i.kind === 'app'),
    [listItems],
  );

  useEffect(() => { setSelectedIndex(0); }, [listItems]);

  useEffect(() => {
    const list = listRef.current;
    if (!list) return;
    const rows = list.querySelectorAll<HTMLElement>('[data-selectable]');
    rows[selectedIndex]?.scrollIntoView({ block: 'nearest' });
  }, [selectedIndex]);

  const confirm = useCallback((app: AppEntry) => {
    onNavigate(app.hash);
    onClose();
  }, [onNavigate, onClose]);

  const handleKeyDown = useCallback((e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      setSelectedIndex((i) => Math.min(i + 1, selectableItems.length - 1));
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      setSelectedIndex((i) => Math.max(i - 1, 0));
    } else if (e.key === 'Enter') {
      const item = selectableItems[selectedIndex];
      if (item) confirm(item.app);
    } else if (e.key === 'Escape') {
      onClose();
    }
  }, [selectableItems, selectedIndex, confirm, onClose]);

  const handleBackdropClick = useCallback(
    (e: React.MouseEvent) => { if (e.target === e.currentTarget) onClose(); },
    [onClose],
  );

  let selectableCounter = -1;

  return ReactDOM.createPortal(
    <Backdrop onClick={handleBackdropClick}>
      <Panel onClick={(e) => e.stopPropagation()}>

        <SearchWrap>
          <Input
            ref={inputRef}
            placeholder={t('palette.placeholder')}
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            onKeyDown={handleKeyDown}
            aria-label={t('palette.search')}
          />
          <SearchIcon><Search size={17} /></SearchIcon>
          {query && (
            <ClearBtn onClick={() => setQuery('')} aria-label={t('palette.clear')}>
              <X size={12} />
            </ClearBtn>
          )}
        </SearchWrap>

        <Divider />

        <ResultsList ref={listRef}>
          {selectableItems.length === 0 ? (
            <Empty>
              <div className="icon"><Search size={18} /></div>
              <div className="title">{t('palette.noMatch')} <span className="query">&ldquo;{query}&rdquo;</span></div>
              <div className="hint">{t('palette.emptyHint')}</div>
            </Empty>
          ) : (
            listItems.map((item, i) => {
              if (item.kind === 'header') {
                return <SectionHeader key={`h-${i}`}>{item.label}</SectionHeader>;
              }

              selectableCounter += 1;
              const idx = selectableCounter;
              const selected = idx === selectedIndex;

              return (
                <ResultRow
                  key={item.app.id}
                  selected={selected}
                  data-selectable
                  onMouseEnter={() => setSelectedIndex(idx)}
                  onClick={() => confirm(item.app)}
                >
                  <AppIcon color={item.app.color} selected={selected}>{item.app.icon}</AppIcon>
                  <ResultInfo>
                    <ResultLabel selected={selected}>{item.app.label}</ResultLabel>
                    <ResultDesc>{item.app.description}</ResultDesc>
                  </ResultInfo>
                  {item.isRecent && (
                    <RecentTag>
                      <Clock size={10} />
                      {t('palette.recentTag')}
                    </RecentTag>
                  )}
                  <ArrowIcon visible={selected}>
                    <ArrowRight size={14} />
                  </ArrowIcon>
                </ResultRow>
              );
            })
          )}
        </ResultsList>

        <Footer>
          <Hint><Kbd>&uarr;</Kbd><Kbd>&darr;</Kbd>{t('palette.hint.navigate')}</Hint>
          <Hint><Kbd>&crarr;</Kbd>{t('palette.hint.open')}</Hint>
          <Hint><Kbd>esc</Kbd>{t('palette.hint.close')}</Hint>
        </Footer>

      </Panel>
    </Backdrop>,
    document.body,
  );
}
