import { useState, useEffect, useCallback, useRef } from 'react';
import styled from '@emotion/styled';
import { keyframes, css } from '@emotion/react';
import { theme, getSetting, putSetting } from '@atlantis/shared';

// ─── Mood system ─────────────────────────────────────────────────────────────

const STORAGE_KEY = 'widget-cache:pet-state';

type Mood = 'ecstatic' | 'happy' | 'content' | 'lonely' | 'dramatic';

interface PetState {
  lastVisit: number;
  happiness: number; // 0–100
  totalPets: number;
  totalFeeds: number;
  name: string;
}

const DEFAULT_STATE: PetState = {
  lastVisit: Date.now(),
  happiness: 80,
  totalPets: 0,
  totalFeeds: 0,
  name: 'Pixel',
};

function getMood(happiness: number): Mood {
  if (happiness >= 90) return 'ecstatic';
  if (happiness >= 70) return 'happy';
  if (happiness >= 40) return 'content';
  if (happiness >= 20) return 'lonely';
  return 'dramatic';
}

function decayHappiness(state: PetState): number {
  const hoursAway = (Date.now() - state.lastVisit) / 3_600_000;
  if (hoursAway < 0.5) return Math.min(100, state.happiness + 5); // just came back
  if (hoursAway < 2) return state.happiness;
  if (hoursAway < 6) return Math.max(0, state.happiness - 10);
  if (hoursAway < 24) return Math.max(0, state.happiness - 25);
  return Math.max(0, state.happiness - 50);
}

const MOOD_TEXT: Record<Mood, { en: string; pt: string }> = {
  ecstatic: { en: 'Purring loudly!', pt: 'A ronronar alto!' },
  happy:    { en: 'Feeling great~', pt: 'Está ótimo~' },
  content:  { en: 'Chilling...', pt: 'Relaxando...' },
  lonely:   { en: 'Misses you...', pt: 'Tem saudades...' },
  dramatic: { en: 'WHERE WERE YOU?!', pt: 'ONDE ESTAVAS?!' },
};

// ─── Animations ──────────────────────────────────────────────────────────────

const fadeIn = keyframes`
  from { opacity: 0; transform: translateY(4px); }
  to { opacity: 1; transform: translateY(0); }
`;

const breathe = keyframes`
  0%, 100% { transform: scaleY(1); }
  50% { transform: scaleY(1.03); }
`;

const tailSway = keyframes`
  0%, 100% { transform: rotate(-5deg); }
  50% { transform: rotate(8deg); }
`;

const tailSadSway = keyframes`
  0%, 100% { transform: rotate(-2deg); }
  50% { transform: rotate(2deg); }
`;

const blink = keyframes`
  0%, 42%, 44%, 100% { ry: 7; }
  43% { ry: 1; }
`;

const sleepBlink = keyframes`
  0%, 100% { ry: 1; }
`;

const purr = keyframes`
  0%, 100% { transform: translateX(0); }
  25% { transform: translateX(-0.5px); }
  75% { transform: translateX(0.5px); }
`;

const floatUp = keyframes`
  0% { opacity: 1; transform: translate(0, 0) scale(1); }
  100% { opacity: 0; transform: translate(var(--dx), -40px) scale(0.5); }
`;

const zzz = keyframes`
  0% { opacity: 0; transform: translate(0, 0) scale(0.5); }
  30% { opacity: 1; transform: translate(4px, -8px) scale(0.8); }
  100% { opacity: 0; transform: translate(10px, -20px) scale(1); }
`;

const earDroop = keyframes`
  0%, 100% { transform: rotate(0deg); }
  50% { transform: rotate(8deg); }
`;

const earDroopR = keyframes`
  0%, 100% { transform: rotate(0deg); }
  50% { transform: rotate(-8deg); }
`;

