// ─── Cat SVG ─────────────────────────────────────────────────────────────────

interface CatProps {
  mood: Mood;
}

function CatSvg({ mood }: CatProps) {
  const isSleepy = mood === 'lonely' || mood === 'dramatic';
  const isHappy = mood === 'ecstatic' || mood === 'happy';

  // Mouth path varies by mood
  const mouth = (() => {
    switch (mood) {
      case 'ecstatic': return 'M 92,104 Q 100,114 108,104'; // big smile
      case 'happy':    return 'M 94,104 Q 100,110 106,104'; // smile
      case 'content':  return 'M 95,105 L 105,105';          // neutral
      case 'lonely':   return 'M 94,108 Q 100,103 106,108'; // frown
      case 'dramatic': return 'M 92,110 Q 100,102 108,110'; // big frown
    }
  })();

  // Eye color by mood
  const eyeColor = isHappy ? '#4ade80' : isSleepy ? '#f97316' : '#58a6ff';

  return (
    <svg viewBox="0 0 200 200" width="140" height="140">
      {/* Tail */}
      <g
        style={{
          transformOrigin: '145px 155px',
          animation: `${isSleepy ? tailSadSway : tailSway} ${isSleepy ? '4s' : '2s'} ease-in-out infinite`,
        }}
      >
        <path
          d="M 140,155 Q 160,130 170,110 Q 175,100 168,95"
          stroke="#7c6f5b"
          strokeWidth="6"
          fill="none"
          strokeLinecap="round"
        />
        <path
          d="M 140,155 Q 160,130 170,110 Q 175,100 168,95"
          stroke="#9a8c78"
          strokeWidth="4"
          fill="none"
          strokeLinecap="round"
        />
      </g>

      {/* Body */}
      <g
        className="cat-body"
        style={{
          transformOrigin: '100px 155px',
          animation: `${breathe} 3s ease-in-out infinite`,
        }}
      >
        <ellipse cx="100" cy="155" rx="40" ry="28" fill="#9a8c78" />
        {/* Belly */}
        <ellipse cx="100" cy="160" rx="25" ry="18" fill="#b5a894" />
      </g>

      {/* Front paws */}
      <ellipse cx="72" cy="175" rx="12" ry="7" fill="#9a8c78" />
      <ellipse cx="128" cy="175" rx="12" ry="7" fill="#9a8c78" />
      {/* Paw pads */}
      <ellipse cx="72" cy="177" rx="5" ry="3" fill="#c4b5a0" />
      <ellipse cx="128" cy="177" rx="5" ry="3" fill="#c4b5a0" />

      {/* Head */}
      <circle cx="100" cy="95" r="36" fill="#9a8c78" />
      {/* Cheek fluff */}
      <ellipse cx="75" cy="100" rx="10" ry="6" fill="#a89880" />
      <ellipse cx="125" cy="100" rx="10" ry="6" fill="#a89880" />

      {/* Left ear */}
      <g
        style={{
          transformOrigin: '78px 68px',
          animation: isSleepy ? `${earDroop} 3s ease-in-out infinite` : undefined,
        }}
      >
        <polygon points="78,68 62,28 92,58" fill="#9a8c78" />
        <polygon points="79,65 67,38 88,58" fill="#e8a0b0" />
      </g>

      {/* Right ear */}
      <g
        style={{
          transformOrigin: '122px 68px',
          animation: isSleepy ? `${earDroopR} 3s ease-in-out infinite` : undefined,
        }}
      >
        <polygon points="122,68 138,28 108,58" fill="#9a8c78" />
        <polygon points="121,65 133,38 112,58" fill="#e8a0b0" />
      </g>

      {/* Forehead stripes */}
      <path d="M 92,70 L 95,80" stroke="#8a7d69" strokeWidth="1.5" strokeLinecap="round" />
      <path d="M 100,68 L 100,78" stroke="#8a7d69" strokeWidth="1.5" strokeLinecap="round" />
      <path d="M 108,70 L 105,80" stroke="#8a7d69" strokeWidth="1.5" strokeLinecap="round" />

      {/* Eyes */}
      <ellipse
        cx="85"
        cy="90"
        rx="7"
        ry={isSleepy ? 1 : 7}
        fill={eyeColor}
        style={!isSleepy ? {
          animation: `${blink} 4s ease-in-out infinite`,
          animationDelay: '0.5s',
        } : {
          animation: `${sleepBlink} 1s ease infinite`,
        }}
      />
      <ellipse
        cx="115"
        cy="90"
        rx="7"
        ry={isSleepy ? 1 : 7}
        fill={eyeColor}
        style={!isSleepy ? {
          animation: `${blink} 4s ease-in-out infinite`,
        } : {
          animation: `${sleepBlink} 1s ease infinite`,
        }}
      />

      {/* Pupils (hidden when sleepy) */}
      {!isSleepy && (
        <>
          <circle cx={isHappy ? 86 : 85} cy={isHappy ? 89 : 90} r={isHappy ? 4 : 3.5} fill="#0d1117" />
          <circle cx={isHappy ? 116 : 115} cy={isHappy ? 89 : 90} r={isHappy ? 4 : 3.5} fill="#0d1117" />
          {/* Eye shine */}
          <circle cx={83} cy={87} r={1.5} fill="white" opacity={0.8} />
          <circle cx={113} cy={87} r={1.5} fill="white" opacity={0.8} />
        </>
      )}

      {/* Nose */}
      <polygon points="100,97 96,101 104,101" fill="#e8a0b0" />

      {/* Mouth */}
      <path d={mouth} stroke="#7c6f5b" strokeWidth="1.5" fill="none" strokeLinecap="round" />

      {/* Whiskers */}
      <line x1="55" y1="96" x2="78" y2="95" stroke="#7c6f5b" strokeWidth="1" opacity="0.6" />
      <line x1="55" y1="102" x2="78" y2="100" stroke="#7c6f5b" strokeWidth="1" opacity="0.6" />
      <line x1="55" y1="108" x2="78" y2="104" stroke="#7c6f5b" strokeWidth="1" opacity="0.6" />
      <line x1="145" y1="96" x2="122" y2="95" stroke="#7c6f5b" strokeWidth="1" opacity="0.6" />
      <line x1="145" y1="102" x2="122" y2="100" stroke="#7c6f5b" strokeWidth="1" opacity="0.6" />
      <line x1="145" y1="108" x2="122" y2="104" stroke="#7c6f5b" strokeWidth="1" opacity="0.6" />

      {/* Sleep zzz */}
      {isSleepy && (
        <>
          <g style={{ animation: `${zzz} 2s ease-in-out infinite` }}>
            <ZzzText x="130" y="72">z</ZzzText>
          </g>
          <g style={{ animation: `${zzz} 2s ease-in-out 0.6s infinite` }}>
            <ZzzText x="140" y="60" fontSize="11">z</ZzzText>
          </g>
          <g style={{ animation: `${zzz} 2s ease-in-out 1.2s infinite` }}>
            <ZzzText x="148" y="48" fontSize="9">z</ZzzText>
          </g>
        </>
      )}

      {/* Happy sparkles */}
      {mood === 'ecstatic' && (
        <>
          <text x="45" y="55" fontSize="10" opacity="0.7">✨</text>
          <text x="148" y="50" fontSize="8" opacity="0.5">✨</text>
        </>
      )}
    </svg>
  );
}

// ─── Component ───────────────────────────────────────────────────────────────

interface PetWidgetProps {
  locale: string;
}

export function PetWidget({ locale }: PetWidgetProps) {
  const [state, setState] = useState<PetState>(DEFAULT_STATE);
  const [loaded, setLoaded] = useState(false);
  const [hearts, setHearts] = useState<Array<{ id: number; dx: number }>>([]);
  const heartId = useRef(0);

  // Load state
  useEffect(() => {
    let cancelled = false;
    (async () => {
      const raw = await getSetting(STORAGE_KEY);
      if (cancelled) return;
      if (raw) {
        try {
          const saved: PetState = JSON.parse(raw);
          const happiness = decayHappiness(saved);
          const updated = { ...saved, happiness, lastVisit: Date.now() };
          setState(updated);
          putSetting(STORAGE_KEY, JSON.stringify(updated));
        } catch {
          setState(DEFAULT_STATE);
        }
      }
      setLoaded(true);
    })();
    return () => { cancelled = true; };
  }, []);

  // Persist on changes
  const persist = useCallback((next: PetState) => {
    setState(next);
    putSetting(STORAGE_KEY, JSON.stringify(next));
  }, []);

  // Pet the cat
  const handlePet = useCallback(() => {
    const id = heartId.current++;
    const dx = (Math.random() - 0.5) * 40;
    setHearts((prev) => [...prev, { id, dx }]);
    setTimeout(() => setHearts((prev) => prev.filter((h) => h.id !== id)), 800);

    setState((prev) => {
      const next = {
        ...prev,
        happiness: Math.min(100, prev.happiness + 8),
        totalPets: prev.totalPets + 1,
        lastVisit: Date.now(),
      };
      putSetting(STORAGE_KEY, JSON.stringify(next));
      return next;
    });
  }, []);

  // Feed the cat
  const handleFeed = useCallback(() => {
    setState((prev) => {
      const next = {
        ...prev,
        happiness: Math.min(100, prev.happiness + 15),
        totalFeeds: prev.totalFeeds + 1,
        lastVisit: Date.now(),
      };
      putSetting(STORAGE_KEY, JSON.stringify(next));
      return next;
    });
  }, []);

  if (!loaded) return null;

  const mood = getMood(state.happiness);
  const moodText = locale === 'pt' ? MOOD_TEXT[mood].pt : MOOD_TEXT[mood].en;

  return (
    <Wrapper>
      <Header>
        <span>
          🐱 <PetName>{state.name}</PetName>
        </span>
        <Stats>
          <span>❤️ {state.totalPets}</span>
          <span>🐟 {state.totalFeeds}</span>
        </Stats>
      </Header>

      <CatArea mood={mood} onClick={handlePet} title={locale === 'pt' ? 'Faz festinhas!' : 'Pet me!'}>
        <CatSvg mood={mood} />
        {hearts.map((h) => (
          <HeartParticle key={h.id} dx={h.dx}>❤️</HeartParticle>
        ))}
      </CatArea>

      <Footer>
        <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
          <MoodText>{moodText}</MoodText>
          <MoodBar>
            <MoodFill pct={state.happiness} mood={mood} />
          </MoodBar>
        </div>
        <ActionBtn onClick={(e) => { e.stopPropagation(); handleFeed(); }}>
          🐟 {locale === 'pt' ? 'Dar comida' : 'Feed'}
        </ActionBtn>
      </Footer>
    </Wrapper>
  );
}
